class IncomingQualityIT extends IncomingQualityFixture {
 @Test void completeChainOnlyIndependentQaMakesLotEligibleAndHistoryVerifies(){var request=request();var sample=sample(request);var task=task(request,sample);var execution=execution(task);var result=result(task,execution,"2","PASS");long resultSignature=Long.parseLong(result.path("signatureId").asText());review(task,result);assertThat(queries.evaluate(1,Long.parseLong(lot),"ISSUE",Instant.now()).path("eligible").asBoolean()).isFalse();assertThat(verifier.verify(1,resultSignature)).isTrue();var report=report(request);as(qa);var gate=service.releaseReview(lot);assertThat(gate.path("eligibleForRelease").asBoolean()).isTrue();String k=key();var command=body("decision","RELEASED","releaseBasis","FULL_INSPECTION","inspectionReportId",id(report),"reason","Independent QA release","reauthToken","token");var release=service.decideRelease(lot,command,token(gate),k);assertThat(service.decideRelease(lot,command,token(gate),k)).isEqualTo(release);assertThat(queries.evaluate(1,Long.parseLong(lot),"ISSUE",Instant.now()).path("eligible").asBoolean()).isTrue();assertThat(verifier.verify(1,Long.parseLong(release.path("signatureId").asText()))).isTrue();var chain=queries.getLotChain(1,Long.parseLong(lot));assertThat(chain.path("requests").get(0).path("samplingTasks").get(0).path("details").get(0).path("samples")).hasSize(2);assertThat(chain.path("requests").get(0).path("inspectionTasks").get(0).path("items").get(0).path("executions").get(0).path("revisions").get(0).path("resultConclusion").asText()).isEqualTo("PASS");assertThatThrownBy(()->jdbc.update("UPDATE qms_test_result_revision SET result_conclusion='FAIL' WHERE id=?",id(result))).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test void quarantineAndOpenOosBlockReleaseAndFailCannotBeOverwritten(){assertThat(queries.evaluate(1,Long.parseLong(lot),"ISSUE",Instant.now()).path("eligible").asBoolean()).isFalse();var request=request();var sample=sample(request);var task=task(request,sample);var execution=execution(task);var fail=result(task,execution,"4","FAIL");assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM qms_deviation WHERE original_result_revision_id=? AND status='OPEN'",Long.class,id(fail))).isEqualTo(1);var current=get("qms_inspection_task",id(task));assertThatThrownBy(()->service.result(id(fail),true,body("testExecutionId",id(execution),"resultNumeric","2","resultUnitId",unit,"resultConclusion","PASS","reasonForChange","Cannot hide FAIL","reauthToken","token"),token(current),key())).hasMessageContaining("Original FAIL");assertThat(jdbc.queryForObject("SELECT result_conclusion FROM qms_test_result_revision WHERE id=?",String.class,id(fail))).isEqualTo("FAIL");as(qa);assertThat(service.releaseReview(lot).path("gateReasons").toString()).contains("INVESTIGATION_OPEN");}
 @Test void missingRequiredResultAndCrossOrganizationCannotProduceReport(){var request=request();var sample=sample(request);task(request,sample);assertThatThrownBy(()->service.createReport(body("inspectionRequestId",id(request),"reason","Missing"),key())).hasMessageContaining("Required specification item missing");when(contexts.current()).thenReturn(new CurrentPlatformContext(2,analyst,Set.of("INCOMING_TEST"),permissions,"session","scope"));assertThatThrownBy(()->service.get("qms_inspection_request","qms:inspection-request:view",id(request))).isInstanceOf(NoSuchElementException.class);}
 @Test void resultAuditFailureRollsBackSignatureResultOosAndTaskVersion(){var request=request();var sample=sample(request);var task=task(request,sample);var execution=execution(task);long before=get("qms_inspection_task",id(task)).path("versionNo").asLong();long signaturesBefore=jdbc.queryForObject("SELECT COUNT(*) FROM gxp_signature WHERE object_type='TEST_RESULT_REVISION' AND object_id LIKE ?",Long.class,id(execution)+":%");doAnswer(i->{var c=(com.hospital.mes.audit.domain.AuditCommand)i.getArgument(0);if(c.action().equals("RECORD_RESULT"))throw new IllegalStateException("injected incoming audit failure");return i.callRealMethod();}).when(audit).append(any());var tx=new TransactionTemplate(transactions);tx.setPropagationBehavior(org.springframework.transaction.TransactionDefinition.PROPAGATION_NESTED);assertThatThrownBy(()->tx.execute(t->result(task,execution,"4","FAIL"))).hasMessageContaining("injected incoming audit failure");assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM qms_test_result_revision WHERE test_execution_id=?",Long.class,id(execution))).isZero();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM qms_deviation WHERE test_execution_id=?",Long.class,id(execution))).isZero();assertThat(jdbc.queryForObject("SELECT version_no FROM qms_inspection_task WHERE id=?",Long.class,id(task))).isEqualTo(before);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM gxp_signature WHERE object_type='TEST_RESULT_REVISION' AND object_id LIKE ?",Long.class,id(execution)+":%")).isEqualTo(signaturesBefore);}

 @Test void approvedRetestCreatesIndependentExecutionAndNeverChangesOriginalFail(){
  var request=request();var sample=sample(request);var originalTask=task(request,sample);var originalExecution=execution(originalTask);var originalResult=result(originalTask,originalExecution,"4","FAIL");review(originalTask,originalResult);
  String investigation=jdbc.queryForObject("SELECT CAST(id AS CHAR) FROM qms_deviation WHERE original_result_revision_id=?",String.class,id(originalResult));as(reviewer);var inv=service.get("qms_deviation","qms:deviation:view",investigation);inv=service.deviationAction(investigation,"investigate",body("investigationScope","INCOMING_MATERIAL","investigationSummary","Assignable instrument preparation error demonstrated by original raw evidence","reason","Investigate"),token(inv),key());as(approver);inv=service.deviationAction(investigation,"decide",body("investigationScope","INCOMING_MATERIAL","decisionCode","AUTHORIZE_RETEST","disposition","One controlled independent retest","authorizedRetestCount",1,"reauthToken","token","reason","Approve retest"),token(inv),key());long decisionSignature=Long.parseLong(inv.path("decisionSignatureId").asText());as(analyst);var retestTask=task(request,sample);var e=service.execution(retestTask.path("items").get(0).path("id").asText(),true,body("originalExecutionId",id(originalExecution),"approvedInvestigationId",investigation,"rawData",Map.of("readout","independent retest"),"calculationInput",Map.of(),"startedAt",Instant.now().minusSeconds(2).toString(),"completedAt",Instant.now().minusSeconds(1).toString(),"performedBy",Long.toString(analyst),"reason","Approved retest"),token(retestTask),key());assertThat(id(e)).isNotEqualTo(id(originalExecution));var passing=result(retestTask,e,"2","PASS");review(retestTask,passing);assertThatThrownBy(()->service.createReport(body("inspectionRequestId",id(request),"reason","Unresolved competing retest"),key())).hasMessageContaining("Unresolved competing");assertThat(jdbc.queryForObject("SELECT quality_status FROM md_material_lot WHERE id=?",String.class,lot)).isNotEqualTo("QC_PASSED");as(qa);assertThat(service.releaseReview(lot).path("gateReasons").toString()).contains("INVESTIGATION_OPEN");inv=service.get("qms_deviation","qms:deviation:view",investigation);service.deviationAction(investigation,"close",body("investigationScope","INCOMING_MATERIAL","selectedResultRevisionId",id(passing),"originalResultDisposition","INVALID","reauthToken","token","reason","Confirmed assignable cause; approve original invalidity with retained FAIL"),token(inv),key());assertThat(jdbc.queryForObject("SELECT quality_status FROM md_material_lot WHERE id=?",String.class,lot)).isEqualTo("QC_PASSED");assertThat(verifier.verify(1,decisionSignature)).isTrue();assertThat(jdbc.queryForObject("SELECT result_conclusion FROM qms_test_result_revision WHERE id=?",String.class,id(originalResult))).isEqualTo("FAIL");assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM qms_test_execution WHERE original_execution_id=?",Long.class,id(originalExecution))).isEqualTo(1);var report=report(request);assertThat(report.path("items").get(0).path("originalResultRevisionId").asText()).isEqualTo(id(originalResult));assertThat(report.path("items").get(0).path("resultRevisionId").asText()).isEqualTo(id(passing));as(qa);var gate=service.releaseReview(lot);service.decideRelease(lot,body("decision","RELEASED","releaseBasis","RETEST","inspectionReportId",id(report),"reason","Independent QA after controlled investigation","reauthToken","token"),token(gate),key());assertThat(queries.evaluate(1,Long.parseLong(lot),"CHARGE",Instant.now()).path("eligible").asBoolean()).isTrue();
 }
 @Test void lotOwnerAuditFailureRollsBackCoupledRequestAndLot(){
  var draft=service.createRequest(body("materialLotId",lot,"qcSpecificationVersionId",version,"requestType","INITIAL","reason","Incoming inspection","requestedQuantity","10","requestedUnitId",unit,"requestedPackageCount",2,"requestedDate",LocalDate.now(ZoneOffset.UTC).toString(),"priority","NORMAL"),key());
  var lotBefore=jdbc.queryForMap("SELECT quality_status,inventory_status,version_no FROM md_material_lot WHERE id=?",lot);
  doAnswer(i->{var c=(com.hospital.mes.audit.domain.AuditCommand)i.getArgument(0);if(c.action().equals("INCOMING_LOT_SUBMIT_INSPECTION"))throw new IllegalStateException("injected lot audit failure");return i.callRealMethod();}).when(audit).append(any());
  var tx=new TransactionTemplate(transactions);tx.setPropagationBehavior(org.springframework.transaction.TransactionDefinition.PROPAGATION_NESTED);
  assertThatThrownBy(()->tx.execute(t->service.requestAction(id(draft),"submit",body("reason","Submit"),token(draft),key()))).hasMessageContaining("injected lot audit failure");
  assertThat(jdbc.queryForMap("SELECT quality_status,inventory_status,version_no FROM md_material_lot WHERE id=?",lot)).isEqualTo(lotBefore);
  var current=get("qms_inspection_request",id(draft));assertThat(current.path("status").asText()).isEqualTo("DRAFT");assertThat(token(current)).isEqualTo(token(draft));
 }}
